24→export const usePlatformConfig = () => {
25→  return useQuery({
26→    queryKey: ["platform_config"],
27→    queryFn: async (): Promise<PlatformConfig> => {
28→      const { data, error } = await supabase
29→        .from("platform_config")
30→        .select("max_resumes_per_job, max_file_size_mb, resume_retention_days, payg_per_resume_cost, topup_min_amount, topup_dodo_product_id, booking_embed_url")
31→        .limit(1)
32→        .single();
33→      if (error || !data) return DEFAULTS;
34→      return {
35→        ...data,
36→      };
37→    },
38→    retry: false,
39→    placeholderData: DEFAULTS,
40→  });
41→};
