114→/**
115→ * Fetch attachments from Resend API (inbound webhooks only include metadata).
116→ */
117→async function fetchResendAttachments(
118→  resendApiKey: string,
119→  emailId: string,
120→  maxFileSizeBytes: number,
121→): Promise<{ filename: string; content: Uint8Array }[]> {
122→  const attachmentFiles: { filename: string; content: Uint8Array }[] = [];
123→
124→  const listRes = await fetch(
125→    `https://api.resend.com/emails/receiving/${emailId}/attachments`,
126→    { headers: { Authorization: `Bearer ${resendApiKey}` } }
127→  );
128→
129→  if (!listRes.ok) {
130→    console.error("Failed to list Resend attachments:", listRes.status, await listRes.text());
131→    return attachmentFiles;
132→  }
133→
134→  const listData = await listRes.json();
135→  const attachments = listData.data || listData || [];
136→  let count = 0;
137→
138→  for (const att of (Array.isArray(attachments) ? attachments : [])) {
139→    if (count >= MAX_ATTACHMENTS_PER_EMAIL) break;
140→    if (!att.filename || !hasAllowedExtension(att.filename)) continue;
141→    if (att.size && att.size > Math.min(maxFileSizeBytes, MAX_ATTACHMENT_SIZE_BYTES)) continue;
142→
143→    try {
144→      const downloadRes = await fetch(att.download_url);
145→      if (!downloadRes.ok) continue;
146→      const buffer = await downloadRes.arrayBuffer();
147→      if (buffer.byteLength > Math.min(maxFileSizeBytes, MAX_ATTACHMENT_SIZE_BYTES)) continue;
148→      attachmentFiles.push({ filename: att.filename, content: new Uint8Array(buffer) });
149→      count++;
150→    } catch (e) {
151→      console.error(`Failed to download Resend attachment ${att.filename}:`, e);
152→    }
153→  }
154→
155→  return attachmentFiles;
156→}
