41→/**
42→ * Verify webhook signature using HMAC-SHA256.
43→ * Supports X-Webhook-Signature header or a shared secret via query param.
44→ */
45→async function verifyWebhookSignature(req: Request, body: ArrayBuffer): Promise<boolean> {
46→  const secret = Deno.env.get("EMAIL_INGEST_WEBHOOK_SECRET");
47→  if (!secret) {
48→    // If no secret is configured, reject all requests for safety.
49→    // Operators must set EMAIL_INGEST_WEBHOOK_SECRET to enable email ingestion.
50→    console.error("EMAIL_INGEST_WEBHOOK_SECRET not configured — rejecting request");
51→    return false;
52→  }
53→
54→  // Check signature header
55→  const signature = req.headers.get("x-webhook-signature");
56→
57→  if (!signature) {
58→    // Also allow secret as a query parameter (for simpler webhook providers)
59→    const url = new URL(req.url);
60→    const querySecret = url.searchParams.get("secret");
61→    return querySecret === secret;
62→  }
63→
64→  // Verify HMAC-SHA256 signature
65→  try {
66→    const key = await crypto.subtle.importKey(
67→      "raw",
68→      new TextEncoder().encode(secret),
69→      { name: "HMAC", hash: "SHA-256" },
70→      false,
71→      ["verify"]
72→    );
73→
74→    const signatureBytes = Uint8Array.from(
75→      atob(signature),
76→      (c: string) => c.charCodeAt(0)
77→    );
78→
79→    return await crypto.subtle.verify("HMAC", key, signatureBytes, body);
80→  } catch (e) {
81→    console.error("Signature verification failed:", e);
82→    return false;
83→  }
84→}
